?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reportes — Hache Natación</title><style>
:root{--ink:#172033;--muted:#6b778b;--line:#e6ebf1;--paper:#fff;--bg:#f3f6fa;--brand:#123b5d;--ok:#166534;--okbg:#ecfdf3;--warn:#92400e;--warnbg:#fff7ed}
*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Inter,Manrope,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink)}.wrap{max-width:1080px;margin:auto;padding:86px 16px 36px}.eyebrow{font-size:11px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;color:#567089}.head h1{font-size:30px;line-height:1.1;margin:6px 0 7px;letter-spacing:-.025em}.sub{color:var(--muted);font-size:15px;line-height:1.5;margin-bottom:22px}.toolbar{display:grid;grid-template-columns:minmax(180px,260px) auto auto auto;gap:9px;align-items:center;background:var(--paper);padding:12px;border:1px solid var(--line);border-radius:17px;box-shadow:0 8px 28px rgba(15,23,42,.045);margin-bottom:14px}.toolbar input,.toolbar button,.toolbar a{min-height:44px;padding:10px 13px;border-radius:11px;border:1px solid #cbd5e1;font:inherit}.toolbar button{background:var(--ink);color:#fff;font-weight:850;cursor:pointer}.toolbar a{background:#eef3f7;color:var(--ink);text-decoration:none;font-weight:800;text-align:center;display:grid;place-items:center}.toolbar a.pdf{background:var(--brand);color:#fff;border-color:var(--brand)}.loading{opacity:.55;pointer-events:none}.error{display:none;background:#fff1f2;border:1px solid #fecdd3;color:#9f1239;border-radius:13px;padding:12px 14px;margin:0 0 14px;font-size:13px;font-weight:750}.error.show{display:block}.cards{display:grid;grid-template-columns:1.2fr repeat(3,1fr);gap:10px}.card,.panel,.proa{background:var(--paper);border:1px solid var(--line);border-radius:17px;box-shadow:0 8px 28px rgba(15,23,42,.04)}.card{padding:16px}.card.primary{background:linear-gradient(145deg,#172033,#20344e);color:#fff;border-color:transparent}.card.primary .label{color:#c9d5e3}.value{font-size:25px;font-weight:900;letter-spacing:-.035em}.label{font-size:10px;color:var(--muted);text-transform:uppercase;font-weight:900;letter-spacing:.07em;margin-bottom:7px}.proa{margin-top:12px;padding:18px}.section-head{display:flex;align-items:end;justify-content:space-between;gap:10px;margin-bottom:14px}.section-head h2,.section-head h3{margin:0;font-size:19px;letter-spacing:-.02em}.section-head span{color:var(--muted);font-size:12px}.proa-grid{display:grid;grid-template-columns:1fr 1fr 1.35fr;gap:11px}.proa-box{padding:15px;border:1px solid var(--line);border-radius:14px;background:#fbfcfe}.proa-box .value{font-size:23px}.minimo{position:relative;overflow:hidden}.minimo.goal-met{background:linear-gradient(145deg,#fff,#f0fdf4);border-color:#bbf7d0}.minimo.goal-over{background:linear-gradient(145deg,#f7fff9,#eafbf0);border-color:#86efac;box-shadow:0 8px 24px rgba(22,101,52,.08)}.progress{height:10px;background:#e6ebf0;border-radius:999px;overflow:hidden;margin:13px 0 10px}.progress>span{display:block;height:100%;background:linear-gradient(90deg,#123b5d,#2b688e);border-radius:999px;transition:width .35s ease}.goal-met .progress>span,.goal-over .progress>span{background:linear-gradient(90deg,#15803d,#22c55e)}.statusline{display:flex;justify-content:space-between;gap:8px;align-items:center;font-size:12px}.ok{color:var(--ok);font-weight:900;background:var(--okbg);padding:6px 9px;border-radius:999px}.pending{color:var(--warn);font-weight:900;background:var(--warnbg);padding:6px 9px;border-radius:999px}.overachievement{margin-top:8px;color:var(--ok);font-size:11px;font-weight:900;letter-spacing:.01em}.overachievement strong{font-size:13px}.formula{margin-top:13px;padding-top:12px;border-top:1px solid var(--line);color:var(--muted);font-size:12px;line-height:1.55}.panel{margin-top:12px;padding:18px}.history{display:grid;gap:8px}.history-row{display:grid;grid-template-columns:1.1fr 1fr 1fr 1fr auto;gap:10px;align-items:center;padding:11px 12px;border:1px solid var(--line);border-radius:12px}.history-row.head{border:0;background:#f7f9fb;font-size:10px;font-weight:900;letter-spacing:.05em;text-transform:uppercase;color:var(--muted)}.pill{justify-self:start;padding:5px 8px;border-radius:999px;font-size:10px;font-weight:900}.pill.ok{background:var(--okbg);color:var(--ok)}.pill.no{background:#f3f4f6;color:#64748b}.asis-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.asis-item{padding:12px;background:#f8fafc;border:1px solid var(--line);border-radius:12px}.asis-item b{display:block;font-size:20px}.asis-item span{font-size:11px;color:var(--muted)}
@media(max-width:760px){.wrap{padding:80px 12px 28px}.head h1{font-size:27px}.toolbar{grid-template-columns:1fr 1fr}.toolbar input{grid-column:1/-1}.cards{grid-template-columns:1fr 1fr}.card.primary{grid-column:1/-1}.proa-grid{grid-template-columns:1fr}.history-row.head{display:none}.history-row{grid-template-columns:1fr 1fr}.history-row>div:first-child{grid-column:1/-1;font-size:15px;font-weight:900;padding-bottom:7px;border-bottom:1px solid var(--line)}.history-row>div:not(:first-child)::before{content:attr(data-label);display:block;font-size:9px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);font-weight:900;margin-bottom:3px}.asis-grid{grid-template-columns:1fr 1fr}.asis-item:first-child{grid-column:1/-1}}
</style></head><body><main class="wrap"><header class="head"><div id="eyebrow-sede" class="eyebrow">Finanzas</div><h1>Reportes</h1><div id="sub-sede" class="sub">Liquidación mensual Hache Natación</div></header><div id="error" class="error"></div><div id="toolbar" class="toolbar"><input id="periodo" type="month"><button id="ver">Actualizar</button><a id="csv">Exportar CSV</a><a id="pdf" class="pdf" href="#">Descargar PDF</a></div><div id="cards" class="cards"></div><section class="proa"><div class="section-head"><div><div class="eyebrow">Convenio</div><h2 id="convenio-titulo">Distribución Hache</h2></div><span id="periodo-label"></span></div><div id="proa" class="proa-grid"></div><div id="formula" class="formula"></div></section><section class="panel"><div class="section-head"><h3>Historial mensual</h3><span>Últimos 12 meses</span></div><div id="meses" class="history"></div></section><section class="panel"><div class="section-head"><h3>Asistencia del mes</h3></div><div id="asis" class="asis-grid"></div></section></main><iframe id="pdf-download-frame" name="pdf-download-frame" title="Descarga PDF" style="display:none"></iframe><script>
(function(){
const p=document.getElementById('periodo'),c=document.getElementById('cards'),pm=document.getElementById('proa'),m=document.getElementById('meses'),a=document.getElementById('asis'),csv=document.getElementById('csv'),pdf=document.getElementById('pdf'),err=document.getElementById('error'),toolbar=document.getElementById('toolbar'),pl=document.getElementById('periodo-label'),formula=document.getElementById('formula'),convTitle=document.getElementById('convenio-titulo'),eyebrowSede=document.getElementById('eyebrow-sede'),subSede=document.getElementById('sub-sede'),pdfFrame=document.getElementById('pdf-download-frame');
const sede=new URLSearchParams(location.search).get('sede')||'MONTEVERDE';
const now=new Date();p.value=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');
const money=n=>Number(n||0).toLocaleString('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0});
const monthLabel=v=>new Date(v+'-02T12:00:00').toLocaleDateString('es-MX',{month:'long',year:'numeric'});
function setError(t){t=t||'';err.textContent=t;err.classList.toggle('show',!!t)}
async function load(){setError('');toolbar.classList.add('loading');try{
 const r=await fetch('/api/reportes.php?periodo='+encodeURIComponent(p.value)+'&sede='+encodeURIComponent(sede),{cache:'no-store'});let x;try{x=await r.json()}catch(_){throw new Error('El servidor devolvió una respuesta inválida.')}if(!r.ok||!x.ok)throw new Error((x&&x.error)||'No se pudo cargar el reporte.');
 const q=x.convenio_proa,socio=q.socio_nombre||(x.sede&&x.sede.socio)||'Socio';
 eyebrowSede.textContent='Finanzas · '+x.sede.nombre;subSede.textContent='Liquidación mensual Hache Natación · '+socio;convTitle.textContent='Distribución Hache · '+socio;pl.textContent=monthLabel(x.periodo);
 c.innerHTML='<div class="card primary"><div class="label">Total cobrado</div><div class="value">'+money(x.finanzas.total)+'</div></div><div class="card"><div class="label">Mensualidades</div><div class="value">'+money(x.finanzas.mensualidades_total)+'</div></div><div class="card"><div class="label">Inscripciones</div><div class="value">'+money(x.finanzas.inscripciones_total)+'</div></div><div class="card"><div class="label">Intensivos</div><div class="value">'+money(x.finanzas.intensivos_total)+'</div></div>';
 let third='';if(Number(q.minimo)>0){const over=Number(q.sobrecumplido||0);const stateClass=over>0?'goal-over':(q.alcanzado?'goal-met':'');const extra=over>0?'<div class="overachievement">Sobrecumplido por <strong>'+money(over)+'</strong></div>':'';third='<div class="proa-box minimo '+stateClass+'"><div class="label">Mínimo '+socio+'</div><div class="progress"><span style="width:'+(q.progreso||0)+'%"></span></div><div class="statusline"><strong>'+(q.alcanzado?'Objetivo contractual cumplido':Math.round(q.progreso||0)+'% del mínimo')+'</strong>'+(q.alcanzado?'<span class="ok">Alcanzado ✓</span>':'<span class="pending">Faltan '+money(q.faltante)+'</span>')+'</div>'+extra+'</div>';}else{third='<div class="proa-box"><div class="label">Movimientos</div><div class="value">'+(x.finanzas.pagos_count||0)+'</div></div>';}
 pm.innerHTML='<div class="proa-box"><div class="label">Participación Hache</div><div class="value">'+money(q.hache)+'</div></div><div class="proa-box"><div class="label">Participación '+socio+'</div><div class="value">'+money(q.socio)+'</div></div>'+third;
 formula.textContent=socio+' recibe '+q.porcentajes.mensualidades+'% de mensualidades + '+q.porcentajes.intensivos+'% de cursos intensivos + '+q.porcentajes.inscripciones+'% de inscripciones. El resto corresponde a Hache Natación.';
 let hist='<div class="history-row head"><div>Periodo</div><div>Total</div><div>Hache</div><div>'+socio+'</div><div>Mínimo</div></div>';
 if(x.meses&&x.meses.length){x.meses.forEach(function(z){const status=z.minimo_alcanzado===null?'No aplica':(z.minimo_alcanzado?'Alcanzado ✓'+(Number(z.sobrecumplido)>0?' +'+money(z.sobrecumplido):''):'Pendiente');const cls=z.minimo_alcanzado?'ok':'no';hist+='<div class="history-row"><div>'+monthLabel(z.periodo)+'</div><div data-label="Total">'+money(z.total)+'</div><div data-label="Hache">'+money(z.hache)+'</div><div data-label="'+socio+'">'+money(z.socio)+'</div><div data-label="Mínimo"><span class="pill '+cls+'">'+status+'</span></div></div>';});}else{hist+='<div class="history-row"><div>Sin datos</div></div>';}m.innerHTML=hist;
 a.innerHTML='<div class="asis-item"><b>'+(x.asistencia.alumnos_con_asistencia||0)+'</b><span>Alumnos registrados</span></div><div class="asis-item"><b>'+(x.asistencia.presentes||0)+'</b><span>Presentes</span></div><div class="asis-item"><b>'+(Number(x.asistencia.justificadas||0)+Number(x.asistencia.no_justificadas||0))+'</b><span>Ausencias</span></div>';
 csv.href='/api/reportes-exportar.php?desde='+encodeURIComponent(x.desde)+'&hasta='+encodeURIComponent(x.hasta)+'&sede='+encodeURIComponent(x.sede.clave);pdf.dataset.url='/api/reportes-pdf.php?periodo='+encodeURIComponent(x.periodo)+'&sede='+encodeURIComponent(x.sede.clave);
}catch(e){setError(e.message||'No se pudo cargar el reporte.');c.innerHTML='';pm.innerHTML='';m.innerHTML='';a.innerHTML='';}finally{toolbar.classList.remove('loading')}}
document.getElementById('ver').onclick=load;p.onchange=load;
pdf.addEventListener('click',function(e){e.preventDefault();const url=pdf.dataset.url;if(!url)return;pdfFrame.src=url;});
load();
})();
</script></body></html>